-- 01_catalogos_y_base.sql: Tablas base y catálogos de valores (no dependen de nada)

CREATE TABLE "campanas" (
  "campana" TEXT NOT NULL,
  "anio_inicio" SMALLINT NOT NULL,
  "anio_fin" SMALLINT NOT NULL,
  PRIMARY KEY ("campana")
);

CREATE TABLE "participantes" (
  "participante_id" TEXT NOT NULL,
  "genero" TEXT,
  PRIMARY KEY ("participante_id")
);

CREATE TABLE "provincias" (
  "provincia_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" TEXT UNIQUE NOT NULL
);

CREATE TABLE "variedades" (
  "variedad_id" TEXT NOT NULL,
  "nombre_variedad" TEXT,
  PRIMARY KEY ("variedad_id")
);

CREATE TABLE "cat_sustrato" (
  "sustrato_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
  "valor" TEXT NOT NULL,
  "descripcion" TEXT,
  CONSTRAINT "ck_cat_sustrato_valor" CHECK (btrim("valor") <> ''),
  PRIMARY KEY ("sustrato_id")
);

CREATE TABLE "cat_cultivo_asociado" (
  "cultivo_asociado_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
  "valor" TEXT NOT NULL,
  "descripcion" TEXT,
  CONSTRAINT "ck_cat_cultivo_asociado_valor" CHECK (btrim("valor") <> ''),
  PRIMARY KEY ("cultivo_asociado_id")
);

CREATE TABLE "cat_fertilizacion" (
  "fertilizacion_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
  "valor" TEXT NOT NULL,
  "descripcion" TEXT,
  CONSTRAINT "ck_cat_fertilizacion_valor" CHECK (btrim("valor") <> ''),
  PRIMARY KEY ("fertilizacion_id")
);

CREATE TABLE "cat_control_plagas" (
  "control_plagas_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
  "valor" TEXT NOT NULL,
  "descripcion" TEXT,
  CONSTRAINT "ck_cat_control_plagas_valor" CHECK (btrim("valor") <> ''),
  PRIMARY KEY ("control_plagas_id")
);

CREATE TABLE "cat_causa_desuniformidad" (
  "causa_desuniformidad_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
  "valor" TEXT NOT NULL,
  "descripcion" TEXT,
  CONSTRAINT "ck_cat_causa_desuniformidad_valor" CHECK (btrim("valor") <> ''),
  PRIMARY KEY ("causa_desuniformidad_id")
);

CREATE TABLE "cat_sanidad_observada" (
  "sanidad_observada_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
  "valor" TEXT NOT NULL,
  "descripcion" TEXT,
  CONSTRAINT "ck_cat_sanidad_observada_valor" CHECK (btrim("valor") <> ''),
  PRIMARY KEY ("sanidad_observada_id")
);

CREATE TABLE "cat_causa_muerte_plantas" (
  "causa_muerte_plantas_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
  "valor" TEXT NOT NULL,
  "descripcion" TEXT,
  CONSTRAINT "ck_cat_causa_muerte_plantas_valor" CHECK (btrim("valor") <> ''),
  PRIMARY KEY ("causa_muerte_plantas_id")
);

CREATE TABLE "cat_control_malezas" (
  "control_malezas_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
  "valor" TEXT NOT NULL,
  "descripcion" TEXT,
  CONSTRAINT "ck_cat_control_malezas_valor" CHECK (btrim("valor") <> ''),
  PRIMARY KEY ("control_malezas_id")
);

CREATE TABLE "cat_cobertura_suelo" (
  "cobertura_suelo_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
  "valor" TEXT NOT NULL,
  "descripcion" TEXT,
  CONSTRAINT "ck_cat_cobertura_suelo_valor" CHECK (btrim("valor") <> ''),
  PRIMARY KEY ("cobertura_suelo_id")
);

CREATE TABLE "etapas" (
  "etapa_id" INTEGER NOT NULL,
  "nombre" TEXT NOT NULL,
  PRIMARY KEY ("etapa_id")
);

CREATE UNIQUE INDEX "uq_cat_sustrato_valor" ON "cat_sustrato" ("valor");

CREATE UNIQUE INDEX "uq_cat_cultivo_asociado_valor" ON "cat_cultivo_asociado" ("valor");

CREATE UNIQUE INDEX "uq_cat_fertilizacion_valor" ON "cat_fertilizacion" ("valor");

CREATE UNIQUE INDEX "uq_cat_control_plagas_valor" ON "cat_control_plagas" ("valor");

CREATE UNIQUE INDEX "uq_cat_causa_desuniformidad_valor" ON "cat_causa_desuniformidad" ("valor");

CREATE UNIQUE INDEX "uq_cat_sanidad_observada_valor" ON "cat_sanidad_observada" ("valor");

CREATE UNIQUE INDEX "uq_cat_causa_muerte_plantas_valor" ON "cat_causa_muerte_plantas" ("valor");

CREATE UNIQUE INDEX "uq_cat_control_malezas_valor" ON "cat_control_malezas" ("valor");

CREATE UNIQUE INDEX "uq_cat_cobertura_suelo_valor" ON "cat_cobertura_suelo" ("valor");


-- 02_sitios_ensayos_y_etapas.sql: Ciudades, sitios, ensayos y tablas de cada etapa (requiere 01)

CREATE TABLE "ciudades" (
  "ciudad_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" TEXT NOT NULL,
  "provincia_id" INTEGER NOT NULL
);

CREATE TABLE "sitios" (
  "sitio_id" TEXT PRIMARY KEY,
  "participante_id" TEXT NOT NULL,
  "provincia_id" INTEGER,
  "ciudad_id" INTEGER
);

CREATE TABLE "ensayos" (
  "ensayo_id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "campana" TEXT NOT NULL,
  "sitio_id" TEXT NOT NULL,
  "variedad_id" TEXT NOT NULL,
  "anio_multiplicacion" SMALLINT,
  "lote_semillas" TEXT,
  PRIMARY KEY ("ensayo_id")
);

CREATE TABLE "siembra" (
  "ensayo_id" BIGINT NOT NULL,
  "metodo_siembra" TEXT,
  "fecha_siembra" DATE,
  "cantidad_semillas_sembradas" INTEGER,
  "fecha_emergencia" DATE,
  "cantidad_plantulas_emergidas" INTEGER,
  PRIMARY KEY ("ensayo_id")
);

CREATE TABLE "trasplante_maceta" (
  "ensayo_id" BIGINT NOT NULL,
  "ubicacion_contenedor" TEXT,
  "profundidad_contenedor_cm" NUMERIC(5,1),
  "fecha_trasplante_maceta" DATE,
  "cantidad_plantines_trasplantados" INTEGER,
  "cantidad_plantines_implantados" INTEGER,
  PRIMARY KEY ("ensayo_id")
);

CREATE TABLE "trasplante_suelo" (
  "ensayo_id" BIGINT NOT NULL,
  "ubicacion_parcela" TEXT,
  "superficie_parcela_m2" NUMERIC(7,2),
  "fecha_trasplante_suelo" DATE,
  "cantidad_plantines_trasplantados" INTEGER,
  "densidad_plantas_m2" NUMERIC(8,5),
  "cantidad_plantines_implantados" INTEGER,
  PRIMARY KEY ("ensayo_id")
);

CREATE TABLE "labores" (
  "ensayo_id" BIGINT NOT NULL,
  "desbrote" BOOLEAN,
  "tutorado" BOOLEAN,
  "conduccion" TEXT,
  "riego" TEXT,
  PRIMARY KEY ("ensayo_id")
);

CREATE TABLE "crecimiento" (
  "ensayo_id" BIGINT NOT NULL,
  "fecha_primera_floracion" DATE,
  "tolerancia_estres_hidrico" NUMERIC(2,1),
  "tolerancia_quemadura_sol" NUMERIC(2,1),
  "sanidad" NUMERIC(2,1),
  "uniformidad" NUMERIC(2,1),
  "cantidad_plantas_muertas" INTEGER,
  PRIMARY KEY ("ensayo_id")
);

CREATE TABLE "labores_fructificacion" (
  "ensayo_id" BIGINT NOT NULL,
  "raleo_frutos" BOOLEAN,
  "eliminacion_brote_apical" BOOLEAN,
  PRIMARY KEY ("ensayo_id")
);

CREATE TABLE "cosecha_poscosecha" (
  "ensayo_id" BIGINT NOT NULL,
  "cantidad_plantas_cosechadas" INTEGER,
  "color_fruto_cosecha" TEXT,
  "cantidad_frutos_muestra_poscosecha" INTEGER,
  "duracion_poscosecha_dias" INTEGER,
  "condicion_poscosecha" TEXT,
  "fecha_primera_cosecha" DATE,
  "fecha_ultima_cosecha" DATE,
  "peso_total_cosechado_kg" NUMERIC(7,3),
  "total_frutos_cosechados" INTEGER,
  PRIMARY KEY ("ensayo_id")
);

CREATE TABLE "degustacion" (
  "ensayo_id" BIGINT NOT NULL,
  "gusto_general" NUMERIC(2,1),
  "dulce_marcado" BOOLEAN,
  "dulce_intensidad" SMALLINT,
  "acido_marcado" BOOLEAN,
  "acido_intensidad" SMALLINT,
  "jugoso_marcado" BOOLEAN,
  "jugoso_intensidad" SMALLINT,
  "persistente_marcado" BOOLEAN,
  "persistente_intensidad" SMALLINT,
  "olor_tomate_maduro_marcado" BOOLEAN,
  "olor_tomate_maduro_intensidad" SMALLINT,
  "olor_tomate_verde_marcado" BOOLEAN,
  "olor_tomate_verde_intensidad" SMALLINT,
  "mucha_pulpa_marcado" BOOLEAN,
  "mucha_pulpa_intensidad" SMALLINT,
  "poca_pulpa_marcado" BOOLEAN,
  "poca_pulpa_intensidad" SMALLINT,
  "pulpa_dura_marcado" BOOLEAN,
  "pulpa_dura_intensidad" SMALLINT,
  "pulpa_blanda_marcado" BOOLEAN,
  "pulpa_blanda_intensidad" SMALLINT,
  "mucha_semilla_marcado" BOOLEAN,
  "mucha_semilla_intensidad" SMALLINT,
  "poca_semilla_marcado" BOOLEAN,
  "poca_semilla_intensidad" SMALLINT,
  "aguachento_marcado" BOOLEAN,
  "aguachento_intensidad" SMALLINT,
  "pastoso_marcado" BOOLEAN,
  "pastoso_intensidad" SMALLINT,
  "piel_dura_marcado" BOOLEAN,
  "piel_dura_intensidad" SMALLINT,
  PRIMARY KEY ("ensayo_id")
);

CREATE UNIQUE INDEX ON "ciudades" ("nombre", "provincia_id");

-- La agregamos para garantizar, mediante una FK compuesta, que cada SITIO pertenezca a una ciudad de su misma provincia.
CREATE UNIQUE INDEX ON "ciudades" ("ciudad_id", "provincia_id");

CREATE INDEX "idx_ensayos_sitio" ON "ensayos" ("sitio_id");

CREATE INDEX "idx_ensayos_variedad" ON "ensayos" ("variedad_id");

